32	// escapeJSONString 把文字写成 JSON \uXXXX 转义序列（非 BMP 字符用代理项对，
33	// 引号、反斜杠与控制字符按 JSON 规则转义），得到与直接书写字符同义的 JSON
34	// 字符串内容（不含两侧引号）。
35	func escapeJSONString(s string) string {
36		var b strings.Builder
37		for _, r := range s {
38			switch {
39			case r == '"':
40				b.WriteString(`\"`)
41			case r == '\\':
42				b.WriteString(`\\`)
43			case r < 0x20:
44				fmt.Fprintf(&b, `\u%04X`, r)
45			case r < 0x80:
46				b.WriteRune(r)
47			case r <= 0xFFFF:
48				fmt.Fprintf(&b, `\u%04X`, r)
49			default:
50				r -= 0x10000
51				fmt.Fprintf(&b, `\u%04X\u%04X`, 0xD800+(r>>10), 0xDC00+(r&0x3FF))
52			}
53		}
54		return b.String()
55	}
