57	// specialJSON 按写法把文字写入 JSON 字符串字面量：direct 直接书写字符，
58	// escaped 把非 ASCII 与控制字符全部写成 \uXXXX——两种写法解码后是同一文字。
59	func specialJSON(t *testing.T, spelling, s string) string {
60		t.Helper()
61		switch spelling {
62		case "direct":
63			return jsonQuote(s)
64		case "escaped":
65			return `"` + escapeJSONString(s) + `"`
66		default:
67			t.Fatalf("unknown spelling %q", spelling)
