95			`{"id":` + j(specialRuleDecide) + `,"value":false,"conditions":[` +
96			`{"attribute":` + j(specialAttrRegion) + `,"op":"eq","value":` + j(specialRegionHit) + `}]},` +
97			`{"id":` + j(specialRuleUnseen) + `,"value":true,"conditions":[` +
98			`{"attribute":` + j(specialAttrRegion) + `,"op":"eq","value":` + j("上海") + `}]}]}]}`
