263				t.Run(cfgSpelling+"-config/"+ctxSpelling+"-context", func(t *testing.T) {
264					j := func(s string) string { return specialJSON(t, cfgSpelling, s) }
265					jc := func(s string) string { return specialJSON(t, ctxSpelling, s) }
266					cfgRaw := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[` +
267						`{"id":` + j(ruleID) + `,"value":true,"conditions":[` +
268						`{"attribute":` + j(attr) + `,"op":"eq","value":` + j(value) + `},` +
269						`{"attribute":"标签","op":"in","value":["",` + j(value) + `,` + j(value) + `]}]}]}]}`
270					ctxRaw := `{` + jc(attr) + `:` + jc(value) + `,"标签":` + jc(value) + `}`
271					flag := mustParseConfig(t, cfgRaw).Find("f")
272					got := flag.EvaluateExplain(mustParseContext(t, ctxRaw))
273					if got.Reason != EvalRule || got.RuleID == nil || *got.RuleID != ruleID || !got.Value {
274						t.Fatalf("unexpected result: %+v", got.EvalResult)
275					}
276	
277					out := mustMarshalExplain(t, got)
278					// 单行：换行/制表符只能以转义形式出现，输出不得含裸换行。
279					if bytes.ContainsAny(out, "\n") {
280						t.Fatalf("output must be a single line: %q", out)
281					}
282					var m map[string]any
283					if err := json.Unmarshal(out, &m); err != nil {
284						t.Fatalf("output is not one parseable JSON object: %v\n%s", err, out)
285					}
286					// 字符串内容不得变成新字段：顶层恰好五个既有字段。
287					if len(m) != 5 {
288						t.Fatalf("top-level fields changed by string content: %v", m)
289					}
290					for _, k := range []string{"key", "value", "reason", "ruleId", "explanation"} {
291						if _, ok := m[k]; !ok {
292							t.Fatalf("missing field %q in %v", k, m)
293						}
294					}
295					if m["ruleId"] != ruleID {
296						t.Fatalf("ruleId decoded text wrong: %q want %q", m["ruleId"], ruleID)
297					}
298	
299					exp := m["explanation"].(map[string]any)
300					rules := exp["rules"].([]any)
301					rule0 := rules[0].(map[string]any)
302					if rule0["ruleId"] != ruleID {
303						t.Fatalf("explanation ruleId decoded text wrong: %q want %q", rule0["ruleId"], ruleID)
304					}
305					conds := rule0["conditions"].([]any)
306					c0 := conds[0].(map[string]any)
307					// 读回的文字与输入解码后的内容相同：不丢字符、不重复转义。
308					if c0["attribute"] != attr || c0["compareValue"] != value || c0["actualValue"] != value {
309						t.Fatalf("decoded text drifted: %v", c0)
310					}
311					if len(c0) != 6 {
312						t.Fatalf("condition fields changed by string content: %v", c0)
313					}
314					c1 := conds[1].(map[string]any)
315					list := c1["compareValue"].([]any)
316					if len(list) != 3 || list[0] != "" || list[1] != value || list[2] != value {
317						t.Fatalf("in list must keep empty member, duplicates and order: %v", list)
318					}
319	
320					if reference == nil {
321						reference = out
322					} else if !bytes.Equal(out, reference) {
323						t.Fatalf("spelling changed output:\n%s\n!= reference:\n%s", out, reference)
324					}
325				})
326			}
327		}
328	}
329	
330	// TestExplainSpecialAttrMissingVsEmpty 验证含特殊字符的属性名准确区分缺失与
331	// 空值：未提供时 actualValue 为 null、missing 为 true；显式空字符串保留空
332	// 字符串、missing 为 false。属性名的转义写法与直接字符查找同一属性。
333	func TestExplainSpecialAttrMissingVsEmpty(t *testing.T) {
334		// 配置里的属性名用代理项对转义写法（"标签🏷"），上下文里直接书写字符，
335		// 两种写法仍查找同一属性。
336		cfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
337			{"id":"r","value":true,"conditions":[
338				{"attribute":"标签\uD83C\uDFF7","op":"eq","value":""}]}]}]}`
339		flag := mustParseConfig(t, cfg).Find("f")
340	
341		missing := flag.EvaluateExplain(mustParseContext(t, `{}`))
342		c := missing.Explanation.Rules[0].Conditions[0]
343		if c.Attribute != "标签🏷" || !c.Missing || c.ActualValue != nil || c.Match {
344			t.Fatalf("missing attribute must use missing=true/nil actualValue: %+v", c)
345		}
346		if out := mustMarshalExplain(t, missing); !strings.Contains(string(out), `"actualValue":null,"missing":true`) {
347			t.Fatalf("missing attribute must render as null/true: %s", out)
348		}
349	
350		empty := flag.EvaluateExplain(mustParseContext(t, `{"标签🏷":""}`))
351		c = empty.Explanation.Rules[0].Conditions[0]
352		if c.Missing || c.ActualValue == nil || *c.ActualValue != "" || !c.Match {
353			t.Fatalf("explicit empty string must be kept with missing=false: %+v", c)
354		}
355		if empty.Reason != EvalRule {
356			t.Fatalf("empty string must match eq \"\": %+v", empty.EvalResult)
357		}
358		if out := mustMarshalExplain(t, empty); !strings.Contains(string(out), `"actualValue":"","missing":false`) {
359			t.Fatalf("empty string must render as \"\"/false: %s", out)
360		}
